final class TunnelRenderingTest {
    private static final BlockPos P=new BlockPos(1003,5,5);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var hidden=new AtomicBoolean();context.runOnClient(client->{hidden.set(client.gui.hud.isHidden());if(hidden.get())client.gui.hud.toggle();});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1003 8 10");context.waitFor(client->Math.abs(client.player.getX()-1003.5)<.1&&client.level.isLoaded(P),300);server.runCommand("fill 997 3 0 1012 3 14 minecraft:smooth_quartz");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();for(int z=5;z<=6;z++){
            var start=new BlockPos(1001,4,z);var end=new BlockPos(1005,4,z);level.setBlockAndUpdate(start,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));level.setBlockAndUpdate(end,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));if(!BeltConnectorItem.createBelts(level,start,end))throw new AssertionError("Failed to create client test belts");
            for(int x=1001;x<=1005;x++)((BeltBlockEntity)level.getBlockEntity(new BlockPos(x,4,z))).setCasingType(BeltBlockEntity.CasingType.BRASS);
            level.setBlockAndUpdate(new BlockPos(1006,4,z),AllBlocks.DEPOT.defaultBlockState());level.setBlockAndUpdate(new BlockPos(1003,5,z),AllBlocks.BRASS_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X));
        }level.setBlockAndUpdate(new BlockPos(1001,4,4),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.SOUTH));((com.simibubi.create.content.kinetics.base.KineticBlockEntity)level.getBlockEntity(new BlockPos(1001,4,4))).setGeneratedSpeed(-64);});
        context.waitFor(client->client.level.getBlockEntity(P) instanceof BrassTunnelBlockEntity tunnel&&tunnel.hasDistributionBehaviour()&&tunnel.isConnected(false),200);server.runCommand("gamemode creative @p");server.runCommand("tp @p 1003 6 8");server.runCommand("item replace entity @p weapon.mainhand with minecraft:air");context.waitFor(client->!client.player.isSpectator()&&Math.abs(client.player.getY()-6)<.1,200);
        lookTop(context);ValueBoxNativeFrameProbe.tunnel(context,world,P);
        lookTop(context);context.getInput().pressKey(options->options.keyUse);context.waitTicks(7);context.runOnClient(client->{if(client.gui.screen()!=null||((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).getSelectionMode()!=BrassTunnelBlockEntity.SelectionMode.SPLIT)throw new AssertionError("Short mode click changed setting");});
        open(context);var point=coordinate(context,3);context.getInput().setCursorPos(0,0);context.waitTicks(1);context.getInput().setCursorPos(point.x,point.y);
        context.waitFor(client->client.gui.screen() instanceof com.simibubi.create.foundation.blockEntity.behaviour.ValueSettingsScreen screen&&screen.children().stream().filter(com.simibubi.create.foundation.gui.widget.ScheduleEditBox.class::isInstance).map(com.simibubi.create.foundation.gui.widget.ScheduleEditBox.class::cast).anyMatch(input->input.getValue().equals("3")),200);
        context.waitTicks(2);context.takeScreenshot("create-vulkan-brass-tunnel-mode-board");context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null&&((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).getSelectionMode()==BrassTunnelBlockEntity.SelectionMode.FORCED_ROUND_ROBIN&&((BrassTunnelBlockEntity)client.level.getBlockEntity(P.south())).getSelectionMode()==BrassTunnelBlockEntity.SelectionMode.FORCED_ROUND_ROBIN,200);
        open(context);context.getInput().pressKey(InputConstants.KEY_ESCAPE);context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);context.runOnClient(client->{if(((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).getSelectionMode()!=BrassTunnelBlockEntity.SelectionMode.FORCED_ROUND_ROBIN)throw new AssertionError("Escape changed tunnel mode");check(client,P);check(client,P.south());var data=(BrassTunnelBlockEntity.RenderData)((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).getRenderData();if(!data.distributing()||!data.right())throw new AssertionError("Connected top render data missing");});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var tunnel=(BrassTunnelBlockEntity)level.getBlockEntity(P);tunnel.setSelectionMode(BrassTunnelBlockEntity.SelectionMode.SPLIT);try(var tx=Transaction.openOuter()){tunnel.accept(new ItemStack(Items.APPLE,12),Direction.WEST,tx);tx.commit();}});
        context.waitFor(client->count(client,new BlockPos(1006,4,5),Items.APPLE)+count(client,new BlockPos(1006,4,6),Items.APPLE)==12,300);world.getConnection().waitForChunksRender();context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-brass-tunnel-group");
        var before=context.computeOnClient(client->((BeltTunnelRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(P),.5f,null,false)).model.mesh);var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{check(client,P);if(((BeltTunnelRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(P),.5f,null,false)).model.mesh==before)throw new AssertionError("Tunnel mesh did not refresh on reload");});
        var connectedKey=context.computeOnClient(client->{var state=client.level.getBlockState(P);return client.getModelManager().getBlockStateModelSet().get(state).createGeometryKey((net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,P,state,net.minecraft.util.RandomSource.create(42));});
        server.runCommand("setblock 1003 5 6 minecraft:air");context.waitFor(client->!((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).isConnected(false),200);
        context.runOnClient(client->{var block=client.level.getBlockState(P);var model=client.getModelManager().getBlockStateModelSet().get(block);var key=model.createGeometryKey((net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,P,block,net.minecraft.util.RandomSource.create(42));if(key==null||key.equals(connectedKey))throw new AssertionError("Tunnel CT geometry key stayed unchanged after group split");var mesh=net.fabricmc.fabric.api.client.renderer.v1.Renderer.get().mutableMesh();model.emitQuads(mesh.emitter(),(net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,P,block,net.minecraft.util.RandomSource.create(42),face->false);if(mesh.immutableCopy().size()==0)throw new AssertionError("Disconnected tunnel CT mesh empty");});
        server.runCommand("setblock 1003 5 6 create:brass_tunnel[axis=x]");context.waitFor(client->((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).isConnected(false),200);
        // The side sample is an installed filter, using the native item interaction path.
        server.runCommand("tp @p 1000 4 5");server.runCommand("item replace entity @p weapon.mainhand with minecraft:apple 8");context.waitFor(client->client.player.getMainHandItem().is(Items.APPLE)&&Math.abs(client.player.getX()-1000.5)<.1,200);look(context,TunnelSettings.filterPosition(Direction.WEST).add(Vec3.atLowerCornerOf(P)));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P)&&hit.getDirection()==Direction.WEST,200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->((BrassTunnelBlockEntity)client.level.getBlockEntity(P)).filtering.getFilter(Direction.WEST).is(Items.APPLE),200);context.runOnClient(client->{if(client.player.getMainHandItem().getCount()!=8)throw new AssertionError("Side sample consumed apples");});
        server.runCommand("gamemode spectator @p");chunkUnload(context,world);context.runOnClient(client->{if(client.gui.hud.isHidden()!=hidden.get())client.gui.hud.toggle();});
    }
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var first=new BlockPos(1050,5,15);var second=first.south();server.runCommand("tp @p 1050 8 16");context.waitFor(client->Math.abs(client.player.getX()-1050.5)<.1&&client.level.isLoaded(first)&&client.level.isLoaded(second),300);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();for(int z=15;z<=16;z++){
            var start=new BlockPos(1048,4,z);var end=new BlockPos(1052,4,z);level.setBlockAndUpdate(start,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));level.setBlockAndUpdate(end,AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));if(!BeltConnectorItem.createBelts(level,start,end))throw new AssertionError("Chunk fixture belt creation failed");for(int x=1048;x<=1052;x++)((BeltBlockEntity)level.getBlockEntity(new BlockPos(x,4,z))).setCasingType(BeltBlockEntity.CasingType.BRASS);level.setBlockAndUpdate(new BlockPos(1050,5,z),AllBlocks.BRASS_TUNNEL.defaultBlockState().setValue(BeltTunnelBlock.HORIZONTAL_AXIS,Direction.Axis.X));
        }var a=(BrassTunnelBlockEntity)level.getBlockEntity(first);var b=(BrassTunnelBlockEntity)level.getBlockEntity(second);for(int i=0;i<3;i++){a.updateTunnelConnections();b.updateTunnelConnections();}b.setSelectionMode(BrassTunnelBlockEntity.SelectionMode.SYNCHRONIZE);try(var tx=Transaction.openOuter()){b.accept(new ItemStack(Items.DIAMOND,9),Direction.WEST,tx);tx.commit();}level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(1050>>4,1));});
        context.waitFor(client->client.level.getBlockEntity(second) instanceof BrassTunnelBlockEntity b&&b.getStackToDistribute().getCount()==9,200);server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();
        for(int attempt=0;attempt<120&&!unloaded.get();attempt++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var b=(BrassTunnelBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,second);if(b!=null){var belt=b.belt();if(belt!=null)belt.setNetworkState(-64,-64,false,new com.simibubi.create.content.kinetics.KineticGraph.Stress(10000,0,false),java.util.Map.of());for(int i=0;i<10;i++){b.updateTunnelConnections();b.tickDistribution();}}unloaded.set(!level.isLoaded(first));});}
        if(!unloaded.get())throw new AssertionError("Tunnel group scan kept adjacent chunk loaded");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var b=(BrassTunnelBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,second);for(int i=0;i<200;i++){b.updateTunnelConnections();b.tickDistribution();}if(level.isLoaded(first)||b.getStackToDistribute().getCount()!=9)throw new AssertionError("Unloaded group lost its waiting queue or loaded its neighbour");});
        server.runCommand("tp @p 1050 8 16");context.waitFor(client->Math.abs(client.player.getX()-1050.5)<.1&&client.level.getBlockEntity(second) instanceof BrassTunnelBlockEntity b&&b.getStackToDistribute().getCount()==9&&b.getSelectionMode()==BrassTunnelBlockEntity.SelectionMode.SYNCHRONIZE,400);server.runOnServer(ignored->world.getConnection().getServerLevel().getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(1050>>4,1),0));
    }
    private static long count(net.minecraft.client.Minecraft client,BlockPos pos,Item item){if(!(client.level.getBlockEntity(pos) instanceof DepotBlockEntity depot))return 0;return java.util.stream.Stream.concat(depot.inventory.inputs.stream(),depot.inventory.outputs.stream()).filter(slot->slot.stack().is(item)).mapToLong(slot->slot.getAmount()).sum();}
    private static void check(net.minecraft.client.Minecraft client,BlockPos pos){var state=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(pos),.5f,null,false);if(!(state instanceof BeltTunnelRenderer.State tunnel)||tunnel.model.mesh==null||tunnel.model.mesh.size()==0||tunnel.flaps.isEmpty())throw new AssertionError("Extracted tunnel flap mesh missing at "+pos);var belt=(BeltRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(pos.below()),.5f,null,false);if(!belt.cover.isEmpty())throw new AssertionError("Tunnel incorrectly closes the covered belt");}
    private static void look(ClientGameTestContext context,Vec3 target){var rotation=context.computeOnClient(client->{var delta=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y);}
    private static void lookTop(ClientGameTestContext context){look(context,new Vec3(P.getX()+.5,P.getY()+1,P.getZ()+.5));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P)&&TunnelSettings.modeHit(hit),200);}
    private static void open(ClientGameTestContext context){lookTop(context);context.getInput().holdKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof com.simibubi.create.foundation.blockEntity.behaviour.ValueSettingsScreen,200);}
    private static Vec2 coordinate(ClientGameTestContext context,int mode){return context.computeOnClient(client->{var point=((com.simibubi.create.foundation.blockEntity.behaviour.ValueSettingsScreen)client.gui.screen()).getCoordinateOfValue(0,mode);var window=client.getWindow();return new Vec2(point.x*window.getScreenWidth()/window.getGuiScaledWidth(),point.y*window.getScreenHeight()/window.getGuiScaledHeight());});}
}
